CREATE UNIQUE INDEX "context_facts_active_household_single_value_idx" ON "context_facts" USING btree ("subject_household_id","category") WHERE "context_facts"."subject_kind" = 'household' AND "context_facts"."lifecycle" = 'active' AND "context_facts"."category" IN ('background', 'work', 'location');